#!/bin/sh
# wcurl hardening reference (option A) — illustrative, not upstream
set -eu

CURL_MIN_SAFE=7.83.0

curl_version() {
  curl --version | head -n1 | awk '{print $2}'
}

version_ge() {
  # returns 0 if $1 >= $2
  [ "$(printf '%s\n%s\n' "$2" "$1" | sort -V | head -n1)" = "$2" ]
}

sanitize_filename() {
  # reject path traversal and absolute paths
  case "$1" in
    *..*|/*|*/*) echo "ERROR: unsafe filename: $1" >&2; exit 2 ;;
  esac
  printf '%s' "$1"
}

ALLOWED_FLAGS='--progress-bar --http2 --clobber --continue-at --parallel-max-host --config'

validate_curl_options() {
  for tok in $1; do
    case "$tok" in
      -*) case " $ALLOWED_FLAGS " in *" $tok "*) : ;; *) echo "ERROR: disallowed flag: $tok" >&2; exit 3 ;; esac ;;
    esac
  done
}

main() {
  v=$(curl_version)
  if ! version_ge "$v" "$CURL_MIN_SAFE"; then
    echo "WARN: curl $v < $CURL_MIN_SAFE — multi-URL + --output unsafe" >&2
  fi
  # ... argv parsing, URL normalization, curl invocation ...
}

main "$@"
